import { headers } from 'next/headers';

function getBaseUrl() {
  const headerList = headers();
  const host = headerList.get('host');
  if (!host) {
    return 'http://localhost:3000';
  }

  const protocol = host.startsWith('localhost') || host.startsWith('127.0.0.1') ? 'http' : 'https';
  return `${protocol}://${host}`;
}

async function getDashboardData() {
  try {
    const baseUrl = getBaseUrl();
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then((response) => {
        if (!response.ok) {
          throw new Error('Failed to fetch analytics');
        }
        return response.json();
      }),
      fetch(`${baseUrl}/api/notifications`).then((response) => {
        if (!response.ok) {
          throw new Error('Failed to fetch notifications');
        }
        return response.json();
      }),
      fetch(`${baseUrl}/api/settings`).then((response) => {
        if (!response.ok) {
          throw new Error('Failed to fetch settings');
        }
        return response.json();
      })
    ]);

    return { analytics, notifications, settings };
  } catch {
    return {
      analytics: { visitors: 0, conversions: 0 },
      notifications: [{ id: 1, message: 'No notifications available.' }],
      settings: { theme: 'light', emailNotifications: true }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>
      <section>
        <h3>Analytics</h3>
        <pre>{JSON.stringify(analytics, null, 2)}</pre>
      </section>
      <section>
        <h3>Notifications</h3>
        <pre>{JSON.stringify(notifications, null, 2)}</pre>
      </section>
      <section>
        <h3>Settings</h3>
        <pre>{JSON.stringify(settings, null, 2)}</pre>
      </section>
    </div>
  );
}

